package com.chubb.apac.claims.modulith.claim.service;
import com.chubb.apac.claims.modulith.claim.event.ClaimCreatedEvent;import com.chubb.apac.claims.modulith.claim.repository.*;import com.chubb.apac.claims.modulith.claim.service.impl.ClaimCreationServiceImpl;import com.chubb.apac.claims.modulith.common.enums.*;import com.chubb.apac.claims.modulith.incident.event.IncidentReportedEvent;import com.chubb.apac.claims.modulith.incident.model.IncidentType;import java.time.Instant;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.context.ApplicationEventPublisher;import static org.mockito.ArgumentMatchers.any;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class ClaimCreationServiceImplTest {@Mock ClaimRepository claims;@Mock ClaimStatusHistoryRepository history;@Mock ClaimIdGenerator ids;@Mock IncidentProductResolver products;@Mock ApplicationEventPublisher events;ClaimCreationServiceImpl service;@BeforeEach void setup(){service=new ClaimCreationServiceImpl(claims,history,ids,products,events);}
 @Test void createsOneClaimFromIncident(){when(claims.existsByIncidentId("INC-1")).thenReturn(false);when(ids.nextClaimId()).thenReturn("CLM-1");when(products.resolve(IncidentType.MOTOR_ACCIDENT)).thenReturn(ProductType.MOTOR);service.createFromIncident(new IncidentReportedEvent("E1","INC-1","U1",IncidentType.MOTOR_ACCIDENT,Market.SG,Instant.now(),Instant.now(),"C1"));verify(claims).saveAndFlush(any());verify(events).publishEvent(any(ClaimCreatedEvent.class));}
 @Test void duplicateIncidentIsIdempotent(){when(claims.existsByIncidentId("INC-1")).thenReturn(true);service.createFromIncident(new IncidentReportedEvent("E1","INC-1","U1",IncidentType.MOTOR_ACCIDENT,Market.SG,Instant.now(),Instant.now(),"C1"));verify(claims,never()).save(any());}}
